//Fetches the cookie policy set on screen
function getCookiePolicy(){
    var cookiePolicy = "";
    var htmlPolicy = document.body.getAttribute("data-os-cookie-policy");
    if(htmlPolicy){
        if (htmlPolicy.search(/SameSite/i) > -1){
            var pattern = new RegExp(/SameSite=([^&;]+)/i);
            var result = pattern.exec(htmlPolicy);
            cookiePolicy = cookiePolicy + result[0] + ";"; 
        }
        if (htmlPolicy.search(/Secure/i) > -1){
            cookiePolicy = cookiePolicy + "Secure"; 
        }
    }
    return cookiePolicy;
}

function RichWidgets_Tabs_ClientSide_setCookie(name, value) {
    var path = document.location.href;
    path = path.replace(/\/\([^\/]*/, ""); //remove sessionId
    path = path.replace(/https?:\/\/[^\/]*/i, ""); //remove protocol and server
    path = path.replace(/[^\/]+\.[^\.\/]+/, ""); //remove filename
    name = name.replace(/:/g,"_"); // replace colon
    document.cookie = name + "=" + escape(value) + "; path=" + path + "; " + getCookiePolicy();
}

