     part._range = range_start;
    else {
     for (var i = range_start; i <= range_end; ++i) {
      var txt;
      if (i < 10 && range_end >= 10) txt = '0' + i;
      else txt = '' + i;
      part._range[part._range.length] = txt;
     }
