    var h = parseInt(H.innerHTML, 10);
    if (t12) {
     if (/pm/i.test(AP.innerHTML) && h < 12)
      h += 12;
     else if (/am/i.test(AP.innerHTML) && h == 12)
      h = 0;
    }
    var d = date.getDate();
    var m = date.getMonth();
    var y = date.getFullYear();
    date.setHours(h);
    date.setMinutes(parseInt(M.innerHTML, 10));
    date.setFullYear(y);
    date.setMonth(m);
    date.setDate(d);
    this.dateClicked = false;
    this.callHandler();
   };
  })();
