/** keyboard navigation, only for popup calendars */
Calendar._keyEvent = function(ev) {
  var cal = window._dynarch_popupCalendar;
  if (!cal || cal.multiple)
    return false;
  (Calendar.is_ie) && (ev = window.event);
  var act = (Calendar.is_ie || ev.type == "keypress"),
      K = ev.keyCode;
  if (ev.ctrlKey) {
    switch (K) {
      case 37: // KEY left
        act && Calendar.cellClick(cal._nav_pm); cal.change = act;
        break;
      case 38: // KEY up
        act && Calendar.cellClick(cal._nav_py); cal.change = act;
        break;
      case 39: // KEY right
        act && Calendar.cellClick(cal._nav_nm); cal.change = act;
        break;
      case 40: // KEY down
        act && Calendar.cellClick(cal._nav_ny); cal.change = act;
        break;
      default:
        return false;
    }
  } else switch (K) {
    case 32: // KEY space (now)
      Calendar.cellClick(cal._nav_now);
      break;
    case 27: // KEY esc
      act && cal.callCloseHandler();
      break;
    case 9: // TAB key?
      if (cal.change) {
        // if we changed anything, set the new value
        Calendar.cellClick(cal.currentDateEl, ev);
      } else {
        // if we were just tabbing around, leave as it was
        cal.callCloseHandler();
      }
      return true;
      break;
    case 37: // KEY left
    case 38: // KEY up
    case 39: // KEY right
    case 40: // KEY down
      if (act) {
        cal.change = act;
        var prev, x, y, ne, el, step;
        prev = K == 37 || K == 38;
        step = (K == 37 || K == 39) ? 1 : 7;
        function setVars() {
          el = cal.currentDateEl;
          var p = el.pos;
          x = p & 15;
          y = p >> 4;
          ne = cal.ar_days[y][x];
        };setVars();
        function prevMonth() {
          var date = new Date(cal.date);
          date.setDate(date.getDate() - step);
          cal.setDate(date);
        };
        function nextMonth() {
          var date = new Date(cal.date);
          date.setDate(date.getDate() + step);
          cal.setDate(date);
        };
        while (1) {
          switch (K) {
            case 37: // KEY left
              if (--x >= 0)
                ne = cal.ar_days[y][x];
              else {
                x = 6;
                K = 38;
                continue;
              }
              break;
            case 38: // KEY up
              if (--y >= 0)
                ne = cal.ar_days[y][x];
              else {
                prevMonth();
                setVars();
              }
              break;
            case 39: // KEY right
              if (++x < 7)
                ne = cal.ar_days[y][x];
              else {
                x = 0;
                K = 40;
                continue;
              }
              break;
            case 40: // KEY down
              if (++y < cal.ar_days.length)
                ne = cal.ar_days[y][x];
              else {
                nextMonth();
                setVars();
              }
              break;
          }
          break;
        }
        if (ne) {
          if (!ne.disabled)
            Calendar.cellClick(ne);
          else if (prev)
            prevMonth();
          else
            nextMonth();
        }
      }
      break;
    case 13: // KEY enter
      if (act) {
        Calendar.cellClick(cal.currentDateEl, ev); cal.change = act;
      }
      break;
    default:
      return false;
  }
  return Calendar.stopEvent(ev);
};

/**
 *  (RE)Initializes the calendar to the given date and firstDayOfWeek
 */
Calendar.prototype._init = function (firstDayOfWeek, date) {
 var today = new Date(),
  TY = today.getFullYear(),
  TM = today.getMonth(),
  TD = today.getDate();
 this.table.style.visibility = "hidden";
 var year = date.getFullYear();
 if (year < this.minYear) {
  year = this.minYear;
  date.setFullYear(year);
 } else if (year > this.maxYear) {
  year = this.maxYear;
  date.setFullYear(year);
 }
 this.firstDayOfWeek = firstDayOfWeek;
 this.date = new Date(date);
 var month = date.getMonth();
 var mday = date.getDate();
 var no_days = date.getMonthDays();

 // calendar voodoo for computing the first day that would actually be
 // displayed in the calendar, even if it's from the previous month.
 // WARNING: this is magic. ;-)
 date.setDate(1);
 var day1 = (date.getDay() - this.firstDayOfWeek) % 7;
 if (day1 < 0){
   day1 += 7;
 }
 date.setDate(-day1);
 date.setDate(date.getDate() + 1);

 var row = this.tbody.firstChild;
 var MN = Calendar._SMN[month];
 var ar_days = this.ar_days = new Array();
 var weekend = Calendar._TT["WEEKEND"];
 var dates = this.multiple ? (this.datesCells = {}) : null;
 for (var i = 0; i < 6; ++i, row = row.nextSibling) {
  var cell = row.firstChild;
  if (this.weekNumbers) {
   cell.className = "day wn";
   cell.innerHTML = date.getWeekNumber();
   cell = cell.nextSibling;
  }
  row.className = "daysrow";
  var previousDay;
  var hasdays = false, iday, dpos = ar_days[i] = [];
  for (var j = 0; j < 7; ++j, cell = cell.nextSibling, date.setDate(iday + 1)) {
   iday = date.getDate();
   if (iday == previousDay) {
    date.setDate(iday + 1);
    iday = date.getDate();
   } else if (date.getHours() != 0) {
       date.setHours(0);
   }
   var wday = date.getDay();
   cell.className = "day";
   cell.pos = i << 4 | j;
   dpos[j] = cell;
   var current_month = (date.getMonth() == month);
   if (!current_month) {
    if (this.showsOtherMonths) {
     cell.className += " othermonth";
     cell.otherMonth = true;
    } else {
     cell.className = "emptycell";
     cell.innerHTML = "&nbsp;";
     cell.disabled = true;
     continue;
    }
   } else {
    cell.otherMonth = false;
    hasdays = true;
   }
   cell.disabled = false;
   cell.innerHTML = this.getDateText ? this.getDateText(date, iday) : iday;
   previousDay = cell.innerHTML;
   if (dates)
    dates[date.print("%Y%m%d")] = cell;
   if (this.getDateStatus) {
    var status = this.getDateStatus(date, year, month, iday);
    if (this.getDateToolTip) {
     var toolTip = this.getDateToolTip(date, year, month, iday);
     if (toolTip)
      cell.title = toolTip;
    }
    if (status === true) {
     cell.className += " disabled";
     cell.disabled = true;
    } else {
     if (/disabled/i.test(status))
      cell.disabled = true;
     cell.className += " " + status;
    }
   }
   if (!cell.disabled) {
    cell.caldate = new Date(date);
    cell.ttip = "_";
    if (!this.multiple && current_month
        && iday == mday && this.hiliteToday) {
     cell.className += " selected";
     this.currentDateEl = cell;
    }
    if (date.getFullYear() == TY &&
        date.getMonth() == TM &&
        iday == TD) {
     cell.className += " today";
     cell.ttip += Calendar._TT["PART_TODAY"];
    }
    if (weekend.indexOf(wday.toString()) != -1)
     cell.className += cell.otherMonth ? " oweekend" : " weekend";
   }
  }
  if (!(hasdays || this.showsOtherMonths))
   row.className = "emptyrow";
 }
 this.title.innerHTML = Calendar._MN[month] + ", " + year;
 this.onSetTime();
 this.table.style.visibility = "visible";
 this._initMultipleDates();
 // PROFILE
 // this.tooltips.innerHTML = "Generated in " + ((new Date()) - today) + " ms";
};

Calendar.prototype._initMultipleDates = function() {
 if (this.multiple) {
  for (var i in this.multiple) {
   var cell = this.datesCells[i];
